// === Tab: mySketch ===
/**
 * Homage to Vera Molnár: Optimized Dimensional Progression
 * Interference Edition: Background cycle is 1.5x longer than Object cycle.
 */

p5.disableFriendlyErrors = true; 

let cellSize; 
let cols, rows; 
let cubeSide; 
let motionTimer = 0; 
let colorTimer = 0; // オブジェクトの色用タイマー
let state = 0; 

function setup() {
  pixelDensity(1); 
  createCanvas(windowWidth, windowHeight, WEBGL); 
  calculateGrid(); 
  ortho(-width / 2, width / 2, -height / 2, height / 2, 0, 10000); 
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight); 
  calculateGrid(); 
  ortho(-width / 2, width / 2, -height / 2, height / 2, 0, 10000); 
}

function calculateGrid() {
  // 短い方の辺に合わせて3分割するルール
  cellSize = max(width, height) / 3; 
  cols = floor(width / cellSize); 
  rows = floor(height / cellSize); 
  cubeSide = cellSize * 0.22; 
}

function mouseClicked() {
  state = (state + 1) % 3; 
}

function draw() {
  let bgColor, strokeColor; 

  // --- 色の干渉ロジック ---
  if (state === 0) { 
    colorTimer += deltaTime * 0.0002; // 全体の基本スピード

    // 背景の周期をオブジェクトの3倍長く（スピードを遅く）設定
    let bgTimer = colorTimer / 3; 

    let strokeWave = (cos(colorTimer) + 1) * 0.5; 
    let bgWave = (cos(bgTimer) + 1) * 0.5; 

    // 白(255)から黒(0)へ、それぞれの波で線形補間
    bgColor = lerp(255, 0, bgWave); 
    strokeColor = lerp(255, 0, strokeWave); 

  } else if (state === 1) { 
    bgColor = 255; 
    strokeColor = 0;
  } else { 
    bgColor = 0; 
    strokeColor = 255;
  }

  motionTimer += deltaTime * 0.0001; 

  background(bgColor); 

  let totalW = cols * cellSize; 
  let totalH = rows * cellSize; 

  push(); 
  translate(-totalW / 2, -totalH / 2); 
  stroke(strokeColor); 

  for (let j = 0; j < rows; j++) { 
    for (let i = 0; i < cols; i++) { 
      push(); 
      translate(i * cellSize + cellSize / 2, j * cellSize + cellSize / 2); 

      // 次元の進行（1D, 2D, 3D...）
      let dimension = i + j * cols + 1; 
      let fullCubes = floor((dimension - 1) / 3); 
      let extraAxes = (dimension - 1) % 3 + 1;

      // パフォーマンスのため、表示する重なりを最大4層に制限
      let displayLayers = min(fullCubes, 4); 

      for (let n = 0; n <= displayLayers; n++) {
        let axesCount = (n < fullCubes) ? 3 : extraAxes;
        let sides = [axesCount >= 1, axesCount >= 2, axesCount >= 3];

        push();
        let layerScale = 1 - n * 0.15; 
        scale(max(0.1, layerScale)); 

        rotateX(sin(motionTimer + i * 0.2) * TWO_PI); 
        rotateY(cos(motionTimer * 0.8 + j * 0.2) * TWO_PI); 
        rotateZ(sin(motionTimer * 0.5 + (i + j) * 0.1) * PI); 

        rotateX(n * 0.3); 
        rotateZ(n * 0.2);

        draw_cube_fast(cubeSide, sides); 
        pop();
      }
      pop(); 
    }
  }
  pop(); 

  drawOverlay(totalW, totalH, bgColor, strokeColor); 
}

function drawOverlay(totalW, totalH, bg, strk) {
  push(); 
  translate(0, 0, 5000); 
  let gutter = cellSize * 0.12; 
  noStroke(); fill(bg); 
  for (let i = 0; i <= cols; i++) { 
    let x = -totalW / 2 + i * cellSize; 
    rect(x - gutter/2, -totalH/2, gutter, totalH); 
  }
  for (let j = 0; j <= rows; j++) { 
    let y = -totalH / 2 + j * cellSize; 
    rect(-totalW/2, y - gutter/2, totalW, gutter); 
  }
  stroke(strk); strokeWeight(1.5); noFill(); 
  for (let i = 0; i <= cols; i++) { 
    let x = -totalW / 2 + i * cellSize; 
    line(x, -totalH / 2 + gutter/2, x, totalH / 2 - gutter/2); 
  }
  for (let j = 0; j <= rows; j++) { 
    let y = -totalH / 2 + j * cellSize; 
    line(-totalW / 2 + gutter/2, y, totalW / 2 - gutter/2, y); 
  }
  pop(); 
}

function draw_cube_fast(slength, perm) {
  let s = slength / 2; let st = -s; let dH = 2.5; let dW = cellSize * 0.38;
  noFill();

  strokeWeight(1);
  if (perm[0]) drawGroupX(st, s, dH, dW);
  if (perm[1]) drawGroupY(st, s, dH, dW);
  if (perm[2]) drawGroupZ(st, s, dH, dW);

  strokeWeight(2.5);
  if (perm[0]) {
    line(s, s, st, s, s, s); line(s, st, st, s, st, s);
    line(st, st, st, st, st, s); line(st, s, st, st, s, s);
  }
  if (perm[1]) {
    line(st, st, st, st, s, st); line(st, st, s, st, s, s);
    line(s, st, st, s, s, st); line(s, st, s, s, s, s);
  }
  if (perm[2]) {
    line(st, st, st, s, st, st); line(st, st, s, s, st, s);
    line(st, s, st, s, s, st); line(st, s, s, s, s, s);
  }
}

function drawGroupX(s, e, dH, dW) {
  line(s, s+dH, s-dW, s, s+dH, e+dW); line(s, s-dH, s-dW, s, s-dH, e+dW);
  line(e, s+dH, s-dW, e, s+dH, e+dW); line(e, s-dH, s-dW, e, s-dH, e+dW);
  line(e, e+dH, s-dW, e, e+dH, e+dW); line(e, e-dH, s-dW, e, e-dH, e+dW);
  line(s, e+dH, s-dW, s, e+dH, e+dW); line(s, e-dH, s-dW, s, e-dH, e+dW);
}
function drawGroupY(s, e, dH, dW) {
  line(s+dH, s-dW, s, s+dH, e+dW, s); line(s-dH, s-dW, s, s-dH, e+dW, s);
  line(s+dH, s-dW, e, s+dH, e+dW, e); line(s-dH, s-dW, e, s-dH, e+dW, e);
  line(e+dH, s-dW, s, e+dH, e+dW, s); line(e-dH, s-dW, s, e-dH, e+dW, s);
  line(e+dH, s-dW, e, e+dH, e+dW, e); line(e-dH, s-dW, e, e-dH, e+dW, e);
}
function drawGroupZ(s, e, dH, dW) {
  line(s-dW, s+dH, s, e+dW, s+dH, s); line(s-dW, s-dH, s, e+dW, s-dH, s);
  line(s-dW, s+dH, e, e+dW, s+dH, e); line(s-dW, s-dH, e, e+dW, s-dH, e);
  line(s-dW, e+dH, s, e+dW, e+dH, s); line(s-dW, e-dH, s, e+dW, e-dH, s);
  line(s-dW, e+dH, e, e+dW, e+dH, e); line(s-dW, e-dH, e, e+dW, e-dH, e);
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
